import React, { useState, useEffect } from 'react';
import { getFranchises, getAssociatedFranchises, createuserExamData, updateuserExamData, deleteuserExamData } from '../services/api'; // Import the necessary APIs

const UserExamData = () => {
  const [filterFranchiseId, setFilterFranchiseId] = useState('');
  const [franchises, setFranchises] = useState([]);
  const [userexamDataList, setuserExamDataList] = useState([]);
  const [editingExam, setEditingExam] = useState(null); // State for the exam being edited
  const [newExam, setNewExam] = useState({ examName: '', date: '', studentsAttended: '' }); // State for new exam data

  // Fetch all franchises on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []);

  // Fetch associated franchises
  useEffect(() => {
    const fetchAssociatedFranchises = async () => {
      try {
        const response = await getAssociatedFranchises(); // Fetch associated franchises
        setFranchises(response.data);
      } catch (error) {
        console.error('Error fetching associated franchises:', error);
        alert('Failed to fetch associated franchises');
      }
    };

    fetchAssociatedFranchises();
  }, []);

  // Get exams based on selected franchise
  const getFranchiseExams = (franchiseId) => {
    const franchise = franchises.find((f) => f._id === franchiseId);
    return franchise ? franchise.userexamData : [];
  };

  // Handle filter change for franchise
  const handleFilterChange = (e) => {
    const selectedFranchiseId = e.target.value;
    setFilterFranchiseId(selectedFranchiseId);
    if (selectedFranchiseId) {
      const exams = getFranchiseExams(selectedFranchiseId);
      setuserExamDataList(exams);
    } else {
      setuserExamDataList([]);
    }
  };

  // Handle delete exam
  const handleDeleteExam = async (examId) => {
    try {
      await deleteuserExamData(filterFranchiseId, examId); // Pass franchiseId and examId to delete
      setuserExamDataList(userexamDataList.filter((exam) => exam._id !== examId));
      alert('Exam deleted successfully');
    } catch (error) {
      console.error('Error deleting exam:', error);
      alert('Failed to delete exam');
    }
  };

  // Handle edit exam
  const handleEditExam = (exam) => {
    setEditingExam(exam);
  };

  // Handle form input changes for editing
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setEditingExam((prevExam) => ({
      ...prevExam,
      [name]: value,
    }));
  };

  // Handle save exam (update the exam data)
  const handleSaveExam = async (e) => {
    e.preventDefault();
    if (!editingExam.franchiseId || !editingExam._id) {
      console.error('Missing franchiseId or _id in editingExam:', editingExam);
      return;
    }

    try {
      const updatedExam = await updateuserExamData(editingExam);
      setuserExamDataList((prevData) =>
        prevData.map((exam) => (exam._id === updatedExam._id ? updatedExam : exam))
      );
      setEditingExam(null); // Close the edit form
      alert('Exam updated successfully');
    } catch (error) {
      console.error('Error saving exam data:', error);
      alert('Failed to update exam');
    }
  };

  // Handle new exam form input changes
  const handleNewExamInputChange = (e) => {
    const { name, value } = e.target;
    setNewExam((prevExam) => ({
      ...prevExam,
      [name]: value,
    }));
  };

  // Handle creating a new exam
  const handleCreateExam = async (e) => {
    e.preventDefault();
    const userexamData = {
      ...newExam,
      franchiseId: filterFranchiseId,
    };

    try {
      await createuserExamData(userexamData); // Call the API to create the exam data
      alert('Exam created successfully');
      // Refresh the exams for the selected franchise
      setuserExamDataList(getFranchiseExams(filterFranchiseId));
      setNewExam({ examName: '', date: '', studentsAttended: '' }); // Reset new exam form
    } catch (error) {
      console.error('Error creating exam:', error);
      alert('Failed to create exam');
    }
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>

      {/* Franchise filter dropdown */}
      <div>
        <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
        <select
          id="filterFranchiseId"
          name="filterFranchiseId"
          value={filterFranchiseId}
          onChange={handleFilterChange}
        >
          <option value="">All</option>
          {franchises.map((franchise) => (
            <option key={franchise._id} value={franchise._id}>
              {franchise.name}
            </option>
          ))}
        </select>
      </div>

      {/* Render new exam form if a franchise is selected */}
      {filterFranchiseId && (
        <div>
          <h2>Create New Exam</h2>
          <form onSubmit={handleCreateExam}>
            <div>
              <label>Exam Name:</label>
              <input
                type="text"
                name="examName"
                value={newExam.examName}
                onChange={handleNewExamInputChange}
              />
            </div>
            <div>
              <label>Date:</label>
              <input
                type="date"
                name="date"
                value={newExam.date}
                onChange={handleNewExamInputChange}
              />
            </div>
            <div>
              <label>Students Attended:</label>
              <input
                type="number"
                name="studentsAttended"
                value={newExam.studentsAttended}
                onChange={handleNewExamInputChange}
              />
            </div>
            <button type="submit">Create Exam</button>
          </form>
        </div>
      )}

      {/* Render edit form if editing an exam */}
      {editingExam ? (
        <div>
          <h2>Edit Exam</h2>
          <form onSubmit={handleSaveExam}>
            <div>
              <label>Exam Name:</label>
              <input
                type="text"
                name="examName"
                value={editingExam.examName}
                onChange={handleInputChange}
              />
            </div>
            <div>
              <label>Date:</label>
              <input
                type="date"
                name="date"
                value={editingExam.date}
                onChange={handleInputChange}
              />
            </div>
            <div>
              <label>Students Attended:</label>
              <input
                type="number"
                name="studentsAttended"
                value={editingExam.studentsAttended}
                onChange={handleInputChange}
              />
            </div>
            <button type="submit">Save Changes</button>
            <button type="button" onClick={() => setEditingExam(null)}>
              Cancel
            </button>
          </form>
        </div>
      ) : (
        <h2>Exam Data</h2>
      )}

      {/* Table to display exam data */}
      {userexamDataList.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {userexamDataList.map((exam, index) => (
              <tr key={index}>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
                <td>
                  <button onClick={() => handleEditExam(exam)}>Edit</button>
                  <button onClick={() => handleDeleteExam(exam._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for the selected franchise.</p>
      )}
    </div>
  );
};

export default UserExamData;
